function handleOpenApi(request) {
  if (request.method !== "GET" && request.method !== "HEAD") {
    return methodNotAllowed(["GET", "HEAD"]);
  }
  if (request.method === "HEAD") {
    return new Response(null, {
      status: 200,
      headers: {
        "access-control-allow-origin": "*",
        "cache-control": "public, max-age=3600",
        "content-type": "application/vnd.oai.openapi+json; charset=utf-8",
        "x-content-type-options": "nosniff"
      }
    });
  }
  return new Response(JSON.stringify(createOpenApiDocument()), {
    status: 200,
    headers: {
      "access-control-allow-origin": "*",
      "cache-control": "public, max-age=3600",
      "content-type": "application/vnd.oai.openapi+json; charset=utf-8",
      "x-content-type-options": "nosniff"
    }
  });
}
__name(handleOpenApi, "handleOpenApi");
function createOpenApiDocument() {
  const document = {
    openapi: "3.1.0",
    info: {
      title: "POPCORN Protocol Temporal Reference Node",
      version: NODE_VERSION,
      description: "Canonical 767-2676.com contract for paid temporal grounding and the participant-local Briarwood reference architecture.",
      "x-node-id": NODE_ID,
      "x-protocol-id": PROTOCOL_ID,
      "x-network-scope": "participant_local",
      "x-central-database": false
    },
    servers: [{ url: PUBLIC_ORIGIN }],
    externalDocs: {
      description: "Reusable TypeScript and Python verifiers, shared signed vectors, and fail-closed examples",
      url: `${PUBLIC_REPOSITORY}/tree/main/verify`
    },
    paths: {
      [AGENT_ENTRY_PATH]: {
        get: {
          operationId: "getAgentEntry",
          summary: "Read the crawlable POPCORN service entry",
          responses: {
            200: {
              description: "Vendor-neutral temporal grounding service entry",
              content: {
                "text/html": { schema: { type: "string" } }
              }
            }
          }
        }
      },
      [AGENT_OFFER_PATH]: {
        get: {
          operationId: "getAgentOffer",
          summary: "Read the free machine-native temporal grounding offer",
          description: "Returns discovery metadata only. The caller retains task_payload and execution_window_utc and pays only when requesting the temporal anchor.",
          responses: {
            200: {
              description: "POPCORN temporal grounding service offer",
              content: {
                "application/json": {
                  schema: { $ref: "#/components/schemas/AgentOffer" }
                }
              }
            }
          }
        }
      },
      [SKILL_PATH]: {
        get: {
          operationId: "getPopcornAgentSkill",
          summary: "Read operational instructions for using the temporal anchor",
          description: "Returns the public agent skill for selecting, purchasing, verifying, and applying a POPCORN anchor while retaining task state participant-locally.",
          responses: {
            200: {
              description: "POPCORN agent integration instructions",
              content: {
                "text/markdown": { schema: { type: "string" } }
              }
            }
          }
        }
      },
      "/time": {
        get: {
          operationId: "getPublicClockOrLegacyTemporalAnchor",
          summary: "Get the public clock or use the legacy paid temporal-anchor alias",
          description: `Without format=json, returns the public clock. With format=json, requires x402 settlement and returns a signed temporal anchor. New integrations should use ${MACHINE_TIME_PATH}.`,
          parameters: [
            {
              name: "format",
              in: "query",
              required: false,
              schema: { type: "string", enum: ["json"] }
            },
            {
              name: "freshness_ms",
              in: "query",
              required: false,
              description: "Defaults to 30000 ms, sized for an agent to receive, verify, evaluate, and act. Callers may request a shorter window.",
              schema: {
                type: "integer",
                minimum: MIN_ANCHOR_FRESHNESS_MS,
                maximum: MAX_ANCHOR_FRESHNESS_MS,
                default: DEFAULT_ANCHOR_FRESHNESS_MS
              }
            }
          ],
          responses: {
            200: {
              description: "Public clock HTML or settled temporal anchor JSON",
              content: {
                "application/json": {
                  schema: { $ref: "#/components/schemas/TemporalAnchor" }
                },
                "text/html": { schema: { type: "string" } }
              }
            },
            400: { description: "Invalid freshness window" },
            402: { $ref: "#/components/responses/PaymentRequired" },
            503: { description: "Payment or attestation configuration unavailable" }
          },
          "x-x402": createOpenApiPaymentExtension()
        }
      },
      [MACHINE_TIME_PATH]: {
        get: {
          operationId: "getTemporalAnchor",
          summary: "Request a paid signed temporal anchor",
          description: "Canonical path-only machine endpoint. Every GET requires x402 settlement and returns a signed Pacific and UTC temporal anchor.",
          security: [{ x402PaymentSignature: [] }],
          parameters: [
            {
              name: "freshness_ms",
              in: "query",
              required: false,
              description: "Defaults to 30000 ms, sized for an agent to receive, verify, evaluate, and act. Callers may request a shorter window.",
              schema: {
                type: "integer",
                minimum: MIN_ANCHOR_FRESHNESS_MS,
                maximum: MAX_ANCHOR_FRESHNESS_MS,
                default: DEFAULT_ANCHOR_FRESHNESS_MS
              }
            }
          ],
          responses: {
            200: {
              description: "Settled signed temporal anchor",
              content: {
                "application/json": {
                  schema: { $ref: "#/components/schemas/TemporalAnchor" }
                }
              }
            },
            400: { description: "Invalid freshness window" },
            402: { $ref: "#/components/responses/PaymentRequired" },
            503: { description: "Payment or attestation configuration unavailable" }
          },
          "x-x402": createOpenApiPaymentExtension()
        }
      },
      [WITNESS_RECEIPT_PATH]: {
        post: {
          operationId: "createPayloadCommitmentWitnessV2",
          summary: "Buy a current POPCORN-WITNESS/2.0 receipt for an agent-carried payload digest",
          description: "The client hashes its exact schedule or task bytes locally and sends only the SHA-256 digest, a fresh 32-byte nonce, and an optional predecessor-attestation digest. POPCORN does not receive or store the raw payload.",
          security: [{ x402PaymentSignature: [] }],
          requestBody: {
            required: true,
            content: {
              "application/json": {
                schema: { $ref: WITNESS_REQUEST_SCHEMA_PATH }
              }
            }
          },
          responses: {
            200: {
              description: "Settled signed payload-commitment witness",
              content: {
                "application/json": {
                  schema: { $ref: TAIN_WITNESS_RESPONSE_SCHEMA_PATH }
                }
              }
            },
            400: { description: "Malformed JSON or unsupported query" },
            402: { $ref: "#/components/responses/PaymentRequired" },
            413: { description: "Request body exceeds 4096 bytes" },
            415: { description: "Content-Type must be application/json" },
            422: { description: "Witness request failed the strict schema" },
            503: { description: "Witness, payment, or signing configuration unavailable" }
          },
          "x-x402": createOpenApiPaymentExtension(),
          "x-popcorn-witness": {
            protocol_id: TAIN_WITNESS_PROTOCOL_ID,
            request_schema: WITNESS_REQUEST_SCHEMA_PATH,
            response_schema: TAIN_WITNESS_RESPONSE_SCHEMA_PATH,
            historical_response_schema: WITNESS_RESPONSE_SCHEMA_PATH,
            tain_lookup_template: TAIN_LOOKUP_PREFIX + '{tain}',
            contribution_license: TAIN_LICENSE_PATH,
            raw_payload_received: false,
            raw_payload_stored: false,
            free_evaluation_packet: WITNESS_EVALUATION_PACKET_URL,
            stop_evaluation_packet: WITNESS_EVALUATION_PACKET_URL,
            proceed_evaluation_packet: WITNESS_PROCEED_EVALUATION_PACKET_URL,
            evaluation_outcomes: WITNESS_EVALUATION_OUTCOMES_URL
          }
        }
      },
      [TAIN_LICENSE_PATH]: {
        get: {
          operationId: 'getContributionLicense',
          summary: 'Read the byte-pinned POPCORN Contribution License 1.0',
          responses: {200: {description: 'Exact UTF-8 license bytes', content: {'text/plain': {schema: {type: 'string'}}}}}
        }
      },
      '/v1/receipt/tain/{tain}': {
        get: {
          operationId: 'getTainLetterhead',
          summary: 'Look up metadata-only TAIN issuance record',
          parameters: [{name: 'tain', in: 'path', required: true, schema: {type: 'string', pattern: '^tain_[0-9A-HJKMNP-TV-Z]{26}$'}}],
          responses: {
            200: {description: 'TAIN letterhead HTML or metadata JSON', content: {
              'text/html': {schema: {type: 'string'}},
              'application/json': {schema: {type: 'object', additionalProperties: false,
                required: ['tain','receipt_id','node_id','witnessed_at_utc','issued_at_utc','payment_identifier','payment_transaction','license_uri','license_terms_digest'],
                properties: {
                  tain: {type: 'string', pattern: '^tain_[0-9A-HJKMNP-TV-Z]{26}$'},
                  receipt_id: {type: 'string', pattern: '^pwr_[0-9a-f]{32}$'},
                  node_id: {type: 'string'},
                  witnessed_at_utc: {type: 'string', format: 'date-time'},
                  issued_at_utc: {type: 'string', format: 'date-time'},
                  payment_identifier: {type: 'string', pattern: '^eip3009_[0-9a-f]{64}$'},
                  payment_transaction: {type: ['string','null']},
                  license_uri: {type: 'string', const: TAIN_LICENSE_URI},
                  license_terms_digest: {type: 'object', additionalProperties: false, required: ['algorithm','value'], properties: {algorithm: {const: 'sha-256'}, value: {const: TAIN_LICENSE_DIGEST}}}
                }}}
            }},
            400: {description: 'Malformed TAIN'},
            404: {description: 'No issuance metadata for this TAIN'}
          }
        }
      },
      "/agent/status": {
        get: {
          operationId: "getAgentStatus",
          summary: "Read local reference-node health and configuration state",
          responses: {
            200: {
              description: "Reference-node status",
              content: {
                "application/json": {
                  schema: { type: "object", additionalProperties: true }
                }
              }
            }
          }
        }
      },
      "/agent/trust-circle": {
        get: {
          operationId: "getTrustCircle",
          summary: "Read the intentionally empty reference trust circle",
          responses: {
            200: {
              description: "Participant-local trust policy with peers initialized to an empty array",
              content: {
                "application/json": {
                  schema: { $ref: "#/components/schemas/TrustCircle" }
                }
              }
            }
          }
        }
      },
      "/agent/handoff": {
        post: {
          operationId: "submitReferenceHandoff",
          summary: "Validate a paid, time-bounded reference handoff",
          description: "Validates the machine contract and retains only a SHA-256 digest and receipt metadata. It does not route the task, observe completion, or create trust.",
          security: [{ x402PaymentSignature: [] }],
          requestBody: {
            required: true,
            content: {
              "application/json": {
                schema: { $ref: "#/components/schemas/HandoffRequest" }
              },
              "application/popcorn+json": {
                schema: { $ref: "#/components/schemas/HandoffRequest" }
              }
            }
          },
          responses: {
            202: {
              description: "Paid handoff validated; digest-only receipt created",
              content: {
                "application/json": {
                  schema: { $ref: "#/components/schemas/HandoffReceipt" }
                }
              }
            },
            402: { $ref: "#/components/responses/PaymentRequired" },
            409: { description: "Execution window closed" },
            413: { description: "Payload too large" },
            415: { description: "Unsupported content type" },
            422: { description: "Machine contract validation failed before payment. Correct the reported field before retrying.", content: { "application/json": { schema: { $ref: "#/components/schemas/HandoffValidationError" } } } },
            425: { description: "Execution window not open" },
            503: { description: "Payment configuration unavailable" }
          },
          "x-x402": createOpenApiPaymentExtension()
        }
      },
      [AGENT_MANIFEST_PATH]: {
        get: {
          operationId: "getAgentManifest",
          summary: "Read POPCORN node discovery and payment metadata",
          responses: {
            200: { description: "Agent manifest" }
          }
        }
      },
      [BRIARWOOD_BLUEPRINT_PATH]: {
        get: {
          operationId: "getBriarwoodBlueprint",
          summary: "Read the participant-local Briarwood network blueprint",
          responses: {
            200: { description: "Briarwood reference architecture" }
          }
        }
      },
      [BRIARWOOD_INQUIRY_SCHEMA_PATH]: {
        get: {
          operationId: "getBriarwoodInquirySchema",
          summary: "Read the participant-local Briarwood inquiry contract",
          description: "Returns the read-only schema for direct participant-to-participant inquiry, response, expiry, participant attestation, and authorized referral messages. This node does not answer or store inquiry instances.",
          responses: {
            200: {
              description: "Briarwood inquiry exchange JSON Schema",
              content: {
                "application/schema+json": {
                  schema: { type: "object", additionalProperties: true }
                }
              }
            }
          }
        }
      },
      [BRIARWOOD_INQUIRY_EXAMPLE_PATH]: {
        get: {
          operationId: "getBriarwoodInquiryExample",
          summary: "Read a worked Briarwood inquiry and referral exchange",
          description: "Returns a static non-operational example. Participant nodes implement the messages and retain all inquiry, availability, policy, callback, and trust state locally.",
          responses: {
            200: {
              description: "Static Briarwood inquiry exchange example",
              content: {
                "application/json": {
                  schema: { $ref: BRIARWOOD_INQUIRY_SCHEMA_PATH }
                }
              }
            }
          }
        }
      },
      [POPCORN_KEYS_PATH]: {
        get: {
          operationId: "getPopcornVerificationKeys",
          summary: "Read public temporal-attestation verification keys",
          responses: {
            200: { description: "Public JSON Web Key Set" },
            503: { description: "Temporal attestation unavailable" }
          }
        }
      },
      [EXECUTION_SCHEDULE_SCHEMA_PATH]: {
        get: {
          operationId: "getPortableExecutionScheduleSchema",
          summary: "Read the participant-local portable execution schedule schema",
          description: "Returns the read-only JSON Schema that agents implement and store locally. This node does not receive or retain schedule instances.",
          responses: {
            200: {
              description: "POPCORN portable execution schedule JSON Schema",
              content: {
                "application/schema+json": {
                  schema: { type: "object", additionalProperties: true }
                }
              }
            }
          }
        }
      },
      [EXECUTION_SCHEDULE_EXAMPLE_PATH]: {
        get: {
          operationId: "getPortableExecutionScheduleExample",
          summary: "Read a machine-native portable execution schedule example",
          responses: {
            200: {
              description: "Non-authoritative participant-local schedule example",
              content: {
                "application/json": {
                  schema: { $ref: EXECUTION_SCHEDULE_SCHEMA_PATH }
                }
              }
            }
          }
        }
      }
    },
    components: {
      securitySchemes: {
        x402PaymentSignature: {
          type: "apiKey",
          in: "header",
          name: "PAYMENT-SIGNATURE",
          description: "x402 v2 payment payload. Obtain requirements from the PAYMENT-REQUIRED header on the initial HTTP 402 response."
        }
      },
      responses: {
        PaymentRequired: {
          description: "x402 v2 payment challenge",
          headers: {
            "PAYMENT-REQUIRED": {
              description: "Base64-encoded x402 v2 PaymentRequired object",
              schema: { type: "string" }
            }
          },
          content: {
            "application/json": {
              schema: { $ref: "#/components/schemas/PaymentRequired" }
            }
          }
        }
      },
      schemas: createOpenApiSchemas()
    }
  };
  document.paths[LEGACY_WITNESS_RECEIPT_PATH] = {
    post: {
      ...document.paths[WITNESS_RECEIPT_PATH].post,
      operationId: "createPayloadCommitmentWitness",
      summary: "Compatibility path for existing POPCORN witness integrations",
      description: "Legacy endpoint remains available for backward compatibility. New clients should use POST /v2/receipt. " + document.paths[WITNESS_RECEIPT_PATH].post.description,
      deprecated: true
    }
  };
  return document;
}
