function handleBriarwoodBlueprint(request) {
  if (request.method !== "GET" && request.method !== "HEAD") {
    return methodNotAllowed(["GET", "HEAD"]);
  }
  const blueprint = {
    blueprint_id: BRIARWOOD_BLUEPRINT_ID,
    blueprint_version: "1.1.0",
    scope: "machine_node_implementation_only",
    deployment_model: "participant_local",
    external_consumer_system_dependency: false,
    central_database: false,
    global_schedule_registry: false,
    global_trust_registry: false,
    initial_peer_state: { peers: [] },
    participant_owns: [
      "task_state",
      "schedule_state",
      "availability_state",
      "callback_state",
      "policy_state",
      "pricing_state",
      "trust_state"
    ],
    popcorn_dependency: {
      purpose: "shared_temporal_anchor",
      endpoint: MACHINE_TIME_PATH,
      participant_stores_anchor: true,
      popcorn_stores_participant_schedule: false,
      popcorn_stores_participant_network: false,
      popcorn_stores_inquiry_instances: false,
      assertion_scope: "time_only"
    },
    portable_execution_schedule: {
      schema: EXECUTION_SCHEDULE_SCHEMA_PATH,
      example: EXECUTION_SCHEDULE_EXAMPLE_PATH,
      storage_location: "participant_local",
      transport_scope: "agent_carried",
      schedule_registry: false,
      event_reset_policy: "terminal_receipt_then_clear_ephemeral_state",
      terminal_receipt_retained: true,
      ephemeral_state_cleared: [
        "resource_lock",
        "payment_proof",
        "retry_counter",
        "transient_task_state"
      ]
    },
    inquiry_state_model: {
      request_states: ["created", "grounded", "submitted"],
      decision_states: [...BRIARWOOD_AVAILABILITY_STATES],
      terminal_states: ["unavailable", "unauthorized", "incompatible", "expired"],
      unavailable_default_action: "terminate",
      unavailable_allowed_actions: [
        "terminate",
        "await_callback",
        "select_authorized_referral"
      ]
    },
    inquiry_contract: {
      protocol_id: BRIARWOOD_INQUIRY_PROTOCOL_ID,
      schema: BRIARWOOD_INQUIRY_SCHEMA_PATH,
      example: BRIARWOOD_INQUIRY_EXAMPLE_PATH,
      publication_scope: "read_only_contract_and_example",
      transport_scope: "participant_to_participant",
      storage_location: "participant_local",
      global_inquiry_endpoint: false,
      global_availability_registry: false,
      request_assertion_owner: "requesting_node",
      response_assertion_owner: "responding_node",
      popcorn_assertion_scope: "time_only"
    },
    required_inquiry_fields: [...BRIARWOOD_INQUIRY_REQUIRED_FIELDS],
    required_response_fields: [...BRIARWOOD_RESPONSE_REQUIRED_FIELDS],
    callback_contract: {
      storage_location: "participant_local",
      automatic_global_registration: false,
      authorization_required: true
    },
    trust_contract: {
      payment_proves_trust: false,
      explicit_authorization_required: true,
      disclosure_default: "private"
    },
    retry_contract: {
      unbounded_retry: false,
      stop_at_execution_window_close: true,
      deadline_clock_source: "last_verified_popcorn_interval_plus_client_monotonic_elapsed",
      backoff: "exponential_with_jitter",
      retry_on_status: [425, 429, 503]
    },
    implementation_note: "The blueprint is implemented in participant storage. 767-2676.com publishes the read-only inquiry contract, supplies temporal anchors, and does not operate a global inquiry, availability, schedule, or trust database."
  };
  return request.method === "HEAD" ? headResponse(200, { "cache-control": "public, max-age=300" }) : jsonResponse(blueprint, 200, { "cache-control": "public, max-age=300" });
}
__name(handleBriarwoodBlueprint, "handleBriarwoodBlueprint");
function createWitnessDigestSchema() {
  return {
    type: "object",
    additionalProperties: false,
    required: ["algorithm", "value"],
    properties: {
      algorithm: { type: "string", const: "sha-256" },
      value: {
        type: "string",
        pattern: "^[A-Za-z0-9_-]{43}$",
        description: "Canonical unpadded base64url encoding of exactly 32 bytes."
      }
    }
  };
}
__name(createWitnessDigestSchema, "createWitnessDigestSchema");
function createWitnessRequestSchema() {
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: `${PUBLIC_ORIGIN}${WITNESS_REQUEST_SCHEMA_PATH}`,
    title: "POPCORN payload-bound witness request v1",
    type: "object",
    additionalProperties: false,
    required: ["payload_digest", "nonce", "previous_attestation_digest"],
    properties: {
      payload_digest: createWitnessDigestSchema(),
      nonce: {
        type: "string",
        pattern: "^[A-Za-z0-9_-]{43}$",
        description: "Canonical unpadded base64url encoding of 32 random bytes."
      },
      previous_attestation_digest: {
        description: "SHA-256 over the exact signed payload bytes of the predecessor compact JWS, obtained by base64url-decoding its second segment. The digest value uses the same canonical unpadded base64url encoding as payload_digest. Null starts a chain.",
        anyOf: [createWitnessDigestSchema(), { type: "null" }]
      }
    }
  };
}
__name(createWitnessRequestSchema, "createWitnessRequestSchema");
function createWitnessResponseSchema() {
  const utcTimestamp = { type: "string", format: "date-time" };
  const nonNegativeInteger = { type: "integer", minimum: 0 };
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: `${PUBLIC_ORIGIN}${WITNESS_RESPONSE_SCHEMA_PATH}`,
    title: "POPCORN payload-bound witness response v1",
    type: "object",
    additionalProperties: false,
    required: ["witness_receipt", "witness_attestation", "payment_status"],
    properties: {
      witness_receipt: {
        type: "object",
        additionalProperties: false,
        required: [
          "receipt_id",
          "node_id",
          "protocol_id",
          "request_received_at_utc",
          "witnessed_at_utc",
          "statement_created_at_utc",
          "unix_time_milliseconds",
          "clock_accuracy_radius_ms",
          "witness_window_utc",
          "server_processing_duration_ms",
          "post_witness_processing_duration_ms",
          "commitment",
          "payment_identifier",
          "payment_transaction",
          "evidence_scope"
        ],
        properties: {
          receipt_id: { type: "string", pattern: "^pwr_[0-9a-f]{32}$" },
          node_id: { type: "string", const: NODE_ID },
          protocol_id: { type: "string", const: WITNESS_PROTOCOL_ID },
          request_received_at_utc: utcTimestamp,
          witnessed_at_utc: utcTimestamp,
          statement_created_at_utc: utcTimestamp,
          unix_time_milliseconds: nonNegativeInteger,
          clock_accuracy_radius_ms: {
            type: "integer",
            minimum: 0,
            maximum: MAX_WITNESS_CLOCK_ACCURACY_RADIUS_MS
          },
          witness_window_utc: {
            type: "object",
            additionalProperties: false,
            required: ["earliest", "latest"],
            properties: { earliest: utcTimestamp, latest: utcTimestamp }
          },
          server_processing_duration_ms: nonNegativeInteger,
          post_witness_processing_duration_ms: nonNegativeInteger,
          commitment: {
            type: "object",
            additionalProperties: false,
            required: ["payload_digest", "nonce", "previous_attestation_digest"],
            properties: {
              payload_digest: createWitnessDigestSchema(),
              nonce: { type: "string", pattern: "^[A-Za-z0-9_-]{43}$" },
              previous_attestation_digest: {
                description: "SHA-256 over the exact signed payload bytes of the predecessor compact JWS, obtained by base64url-decoding its second segment. The digest value uses the same canonical unpadded base64url encoding as payload_digest. Null starts a chain.",
                anyOf: [createWitnessDigestSchema(), { type: "null" }]
              }
            }
          },
          payment_identifier: { type: "string", minLength: 1, maxLength: 256 },
          payment_transaction: {
            anyOf: [{ type: "string", minLength: 1, maxLength: 256 }, { type: "null" }]
          },
          evidence_scope: {
            type: "object",
            additionalProperties: false,
            required: [
              "type",
              "payload_disclosed",
              "caller_identity_proven",
              "recipient_delivery_proven",
              "action_execution_proven",
              "nonce_uniqueness_enforced",
              "replay_prevented",
              "authorization_granted",
              "external_atomic_clock_alignment_proven",
              "clock_accuracy_independently_verified",
              "payer_authorization_bound_to_commitment"
            ],
            properties: {
              type: { type: "string", const: "payload_commitment_witness" },
              payload_disclosed: { type: "boolean", const: false },
              caller_identity_proven: { type: "boolean", const: false },
              recipient_delivery_proven: { type: "boolean", const: false },
              action_execution_proven: { type: "boolean", const: false },
              nonce_uniqueness_enforced: { type: "boolean", const: false },
              replay_prevented: { type: "boolean", const: false },
              authorization_granted: { type: "boolean", const: false },
              external_atomic_clock_alignment_proven: {
                type: "boolean",
                const: false
              },
              clock_accuracy_independently_verified: {
                type: "boolean",
                const: false
              },
              payer_authorization_bound_to_commitment: {
                type: "boolean",
                const: false
              }
            }
          }
        }
      },
      witness_attestation: {
        type: "object",
        additionalProperties: false,
        required: ["format", "algorithm", "key_id", "key_set", "compact_jws"],
        properties: {
          format: { type: "string", const: "JWS" },
          algorithm: { type: "string", const: "ES256" },
          key_id: { type: "string", minLength: 1, maxLength: 128 },
          key_set: { type: "string", const: POPCORN_KEYS_PATH },
          compact_jws: { type: "string", minLength: 1 }
        }
      },
      payment_status: { type: "string", const: "settled" }
    }
  };
}
